import{Mt as e,dt as t,n,pt as r}from"./chunks/framework.CaLsa5bj.js";var i=JSON.parse(`{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1794389503000}`),a={name:`guide/faq.md`};function o(n,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[r(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h1><h2 id="画布没有显示" tabindex="-1">画布没有显示 <a class="header-anchor" href="#画布没有显示" aria-label="Permalink to “画布没有显示”">​</a></h2><p>先检查是否导入 <code>@bubblesjs/workflow-vue-core/style.css</code>，以及设计器的父容器是否有明确高度。<code>Designer</code> 使用 <code>height: 100%</code>，如果父容器高度为零，画布也会不可见。</p><div class="language-css" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.workflow-container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  height</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">640</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">px</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>同时确认绑定了 <code>v-model:nodes</code>，并用 <code>createDefaultNodes()</code> 初始化。一个页面存在多个设计器时，应为每个实例设置不同的 <code>id</code>。</p><h2 id="为什么没有-node-click-事件" tabindex="-1">为什么没有 node-click 事件 <a class="header-anchor" href="#为什么没有-node-click-事件" aria-label="Permalink to “为什么没有 node-click 事件”">​</a></h2><p>开始、结束和添加入口不触发业务节点点击事件。只读模式也不会触发该事件。编辑模式下，点击审批、填写、抄送、条件、分支或循环节点，再通过事件 ID 从 <code>nodes</code> 中读取当前节点。</p><h2 id="能手动拖动节点或修改连线吗" tabindex="-1">能手动拖动节点或修改连线吗 <a class="header-anchor" href="#能手动拖动节点或修改连线吗" aria-label="Permalink to “能手动拖动节点或修改连线吗”">​</a></h2><p>当前设计器使用自动布局，关闭节点拖拽、手动连线和连线更新。数组顺序和 <code>parentNode</code> 决定结构，不需要手动设置 <code>position</code>。当前公开 API 未提供开启这些操作的选项。</p><h2 id="如何设置只读模式" tabindex="-1">如何设置只读模式 <a class="header-anchor" href="#如何设置只读模式" aria-label="Permalink to “如何设置只读模式”">​</a></h2><p>为 <code>Designer</code> 设置 <code>readonly</code>，默认值为 <code>false</code>：</p><div class="language-vue" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Designer</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;workflow-preview&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nodes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nodes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> readonly</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>只读时隐藏添加节点、增加分支和删除入口，禁用鼠标与键盘触发的节点点击，不触发 <code>node-click</code> 或 <code>update:nodes</code>，保留画布平移与缩放。</p><p><code>deletable: false</code> 仅约束单独删除；需要整体只读时，请使用 <code>readonly</code>。</p><h2 id="为什么不能删除-其他-条件" tabindex="-1">为什么不能删除“其他”条件 <a class="header-anchor" href="#为什么不能删除-其他-条件" aria-label="Permalink to “为什么不能删除“其他”条件”">​</a></h2><p>“其他”是条件组的兜底路径，不允许单独删除。每组至少保留两条条件；普通条件只有在总数超过两条时才能删除。需要移除整组时，删除条件分支容器。</p><h2 id="修改条件-label-后标题没有变化" tabindex="-1">修改条件 label 后标题没有变化 <a class="header-anchor" href="#修改条件-label-后标题没有变化" aria-label="Permalink to “修改条件 label 后标题没有变化”">​</a></h2><p>条件卡片的标题由 <code>conditionIndex</code> 和 <code>isDefaultCondition</code> 决定，固定展示“条件规则 N”或“其他”。条件表达式应保存在 <code>data.config</code>，通过自己的业务表单编辑。</p><h2 id="如何添加退出循环" tabindex="-1">如何添加退出循环 <a class="header-anchor" href="#如何添加退出循环" aria-label="Permalink to “如何添加退出循环”">​</a></h2><p>将鼠标移到循环内部的添加入口，菜单中才会出现“退出循环”。它会退出最近的一层循环；循环内的条件路径也支持退出。</p><h2 id="是否提供流程执行能力" tabindex="-1">是否提供流程执行能力 <a class="header-anchor" href="#是否提供流程执行能力" aria-label="Permalink to “是否提供流程执行能力”">​</a></h2><p>组件负责可视化编排，不执行审批、表达式或循环。保存或发布前，需要在业务侧校验配置并转换为目标引擎的数据格式。</p><h2 id="如何用于-ssr-项目" tabindex="-1">如何用于 SSR 项目 <a class="header-anchor" href="#如何用于-ssr-项目" aria-label="Permalink to “如何用于 SSR 项目”">​</a></h2><p>设计器依赖浏览器画布环境，建议仅在客户端加载。在 VitePress 中使用 <code>&lt;ClientOnly&gt;</code> 并通过 <code>defineAsyncComponent</code> 动态导入示例；其他 SSR 框架使用对应的客户端组件机制。示例见<a href="./../examples/#在-vitepress-中加载">交互示例</a>。</p><h2 id="docs-能否独立构建" tabindex="-1">docs 能否独立构建 <a class="header-anchor" href="#docs-能否独立构建" aria-label="Permalink to “docs 能否独立构建”">​</a></h2><p>可以。运行 <code>pnpm docs:build</code> 即可，文档通过源码别名加载本地组件，用于验证当前源码。发布后的外部项目按包的 <code>exports</code> 引用构建产物。文档构建版本固定为 VitePress <code>2.0.0-alpha.21</code>。</p>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};